import{_ as p,b as i,c as a,g as t}from"./chunks/framework.86O3EbG5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/11.md","filePath":"articles/artificial-intelligence/books/AI-modern-approach-homework/11.md"}'),o={name:"articles/artificial-intelligence/books/AI-modern-approach-homework/11.md"};function n(r,e,s,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[t('<p>基于斯图尔特.罗素《人工智能：现代方法（第4版)）》的第 11 章，根据此章节的重点，并出一些从 基础→进阶→综合 的练习题，能让我将本章的知识串联起来。</p><h2 id="简述条件规划与动作序列的本质区别。举一个日常生活中需要条件规划的例子-例如-乘公交上班-遇到公交车满员或故障-并说明如果只用固定序列会有什么后果。" tabindex="-1">简述条件规划与动作序列的本质区别。举一个日常生活中需要条件规划的例子（例如“乘公交上班”遇到公交车满员或故障），并说明如果只用固定序列会有什么后果。</h2><h2 id="画出以下真空吸尘器世界-两个格子a、b-的与或图局部结构" tabindex="-1">画出以下真空吸尘器世界（两个格子A、B）的与或图局部结构：</h2><p>动作 Move(A,B)：有0.8概率成功移动到B，0.2概率仍留在A。</p><p>动作 Suck：确定清除当前格子污渍。</p><p>初始：在A，有污渍。目标：两个格子干净。 要求画出智能体选择动作后的环境分支（即与节点）。</p><h2 id="解释-循环规划-与-无限循环-的区别。对于扫地机器人保持地面清洁的任务-设计一个简单的循环规划-用if-then或loop形式-并说明如何保证它最终退出-或不需要退出-。" tabindex="-1">解释“循环规划”与“无限循环”的区别。对于扫地机器人保持地面清洁的任务，设计一个简单的循环规划（用if-then或loop形式），并说明如何保证它最终退出（或不需要退出）。</h2><h2 id="给定一个简单的与或图-根为或节点-子节点为与节点-各分支表示环境结果-。图中-初始状态s-智能体有两个动作a和b。若选a-则环境可能进入状态s1或s2-若选b-则进入状态s3-唯一-。s1、s2、s3均为目标状态。请写出一个条件规划-伪代码形式-并说明如果环境分支概率不同-a分支概率0-9到s1-0-1到s2-理性智能体应如何决策-假设目标是到达任何目标即可-不考虑代价-。" tabindex="-1">给定一个简单的与或图（根为或节点，子节点为与节点，各分支表示环境结果）。图中：初始状态S，智能体有两个动作A和B。若选A，则环境可能进入状态S1或S2；若选B，则进入状态S3（唯一）。S1、S2、S3均为目标状态。请写出一个条件规划（伪代码形式），并说明如果环境分支概率不同（A分支概率0.9到S1,0.1到S2），理性智能体应如何决策（假设目标是到达任何目标即可，不考虑代价）。</h2><h2 id="设计一个执行监控器用于-家庭服务机器人-任务-任务为-取回客厅茶几上的遥控器-。初始规划为-去客厅-取遥控器-回到沙发-。若机器人在执行中发现遥控器不在茶几上-请描述监控器应如何检测偏差-并给出三种可能的反应-局部修整、重新规划等-。" tabindex="-1">设计一个执行监控器用于“家庭服务机器人”任务，任务为“取回客厅茶几上的遥控器”。初始规划为：[去客厅, 取遥控器, 回到沙发]。若机器人在执行中发现遥控器不在茶几上，请描述监控器应如何检测偏差，并给出三种可能的反应（局部修整、重新规划等）。</h2><h2 id="考虑一个简单资源约束规划-制造两种产品p1、p2。p1每件需2小时人工、1单位材料a-p2每件需1小时人工、2单位材料a。初始有10小时人工、6单位材料。目标-生产至少3件p1和2件p2。" tabindex="-1">考虑一个简单资源约束规划：制造两种产品P1、P2。P1每件需2小时人工、1单位材料A；P2每件需1小时人工、2单位材料A。初始有10小时人工、6单位材料。目标：生产至少3件P1和2件P2。</h2><p>将此问题建模为线性规划或整数规划（列出变量和约束）。</p><p>如果人工时间连续可分，求最优生产方案。</p><p>若人工必须为整数，用贪心或简单推理给出近似解。</p><h2 id="分层规划-htn-建模" tabindex="-1">分层规划（HTN）建模</h2><p>使用HTN规划方法为“做一顿中餐（四菜一汤）”建立分层模型。定义顶层任务 MakeMeal，分解为 PrepareIngredients, CookDishes, Serve。进一步分解 CookDishes 为 SteamFish, StirFryVeg, BoilSoup 等。写出至少两个方法的分解规则（包括前提条件）。讨论如果某道菜（如清蒸鱼）缺少原料，HTN规划器应如何通过前提条件避免不可行的分解。</p><h2 id="连续规划与调度" tabindex="-1">连续规划与调度</h2><p>你负责组织一次学术会议，需要安排多个报告（每个报告有固定时长）在几个并行会议室中，并考虑：同一时间段同一会议室只能有一个报告；某些报告需要投影设备（只有两套）；报告人有特殊时间约束（只能上午或下午）。</p><p>将此问题形式化为一个约束满足+资源调度问题。</p><p>设计一个简单的贪心调度算法，并评估其可能的最坏情况。</p><h2 id="规划与执行的闭环系统" tabindex="-1">规划与执行的闭环系统</h2><p>设计一个“自动家庭割草机器人”的规划与执行架构。机器人已知庭院地图（完全可观测），但草的生长速度不确定，且可能遇到临时障碍物（如孩子玩具）。要求：</p><p>描述机器人的感知、规划、执行、监控模块。</p><p>什么情况下需要重新规划？设计一个简单的触发条件。</p><p>讨论如果机器人电量不足，应如何修改规划（例如返回充电站）。</p><h2 id="条件规划与强化学习" tabindex="-1">条件规划与强化学习</h2><p>条件规划与强化学习（第22章）都可用于非确定性环境。请从以下角度比较两者：</p><p>知识表示（是否需要显式模型？）</p><p>算法的输出（条件规划 vs 策略）</p><p>在线执行中的适应性</p><p>举例说明哪些问题更适合条件规划，哪些更适合强化学习。</p>',30)])])}const S=p(o,[["render",n]]);export{_ as __pageData,S as default};
